fun stringsFor(language: AppLanguage): UiStrings = when (language) {
    AppLanguage.ENGLISH -> EnStrings
    AppLanguage.CHINESE_SIMPLIFIED -> ZhStrings
}

/** Compose entry point: screens read [LocalStrings].current. */
val LocalStrings = staticCompositionLocalOf<UiStrings> { EnStrings }

/** Process-wide language for non-Compose call sites (repositories, services, notifications). */
object AppLocale {
    private val _language = MutableStateFlow(AppLanguage.ENGLISH)
    val language: StateFlow<AppLanguage> = _language.asStateFlow()

    @Volatile
    private var current: UiStrings = EnStrings

    fun strings(): UiStrings = current

    fun currentLanguage(): AppLanguage = _language.value

    fun apply(language: AppLanguage) {
        current = stringsFor(language)
        if (_language.value != language) _language.value = language
        val locale = language.locale
        if (Locale.getDefault() != locale) Locale.setDefault(locale)
    }
}
